// SPDX-License-Identifier: MIT
pragma solidity ^0.8.19;

import "@openzeppelin/contracts/security/ReentrancyGuard.sol";
import "@openzeppelin/contracts/access/Ownable.sol";

/**
 * @title MultiSigVault
 * @notice A multi-signature vault that requires k-of-n approvals for withdrawals.
 * @dev Uses EIP-712 style structured signing for off-chain approval collection.
 *      Signers submit approvals referencing a unique proposal hash.
 */
contract MultiSigVault is ReentrancyGuard, Ownable {
    uint256 public constant MAX_SIGNERS = 20;
    uint256 public requiredApprovals;

    mapping(address => bool) public isSigner;
    address[] public signers;

    struct Proposal {
        address recipient;
        uint256 amount;
        string memo;
        uint256 nonce;
        bool executed;
        uint256 approvalCount;
        mapping(address => bool) hasApproved;
    }

    mapping(bytes32 => Proposal) public proposals;
    mapping(address => uint256) public signerNonces;
    uint256 public globalNonce;

    event ProposalCreated(bytes32 indexed proposalId, address recipient, uint256 amount, string memo);
    event ProposalApproved(bytes32 indexed proposalId, address indexed signer);
    event ProposalExecuted(bytes32 indexed proposalId, address recipient, uint256 amount);
    event SignerAdded(address indexed signer);
    event SignerRemoved(address indexed signer);

    modifier onlySigner() {
        require(isSigner[msg.sender], "Not a signer");
        _;
    }

    constructor(address[] memory _signers, uint256 _requiredApprovals) {
        require(_signers.length >= _requiredApprovals, "Invalid threshold");
        require(_requiredApprovals > 0, "Need at least 1 approval");
        require(_signers.length <= MAX_SIGNERS, "Too many signers");

        for (uint256 i = 0; i < _signers.length; i++) {
            require(_signers[i] != address(0), "Invalid signer");
            require(!isSigner[_signers[i]], "Duplicate signer");
            isSigner[_signers[i]] = true;
            signers.push(_signers[i]);
        }
        requiredApprovals = _requiredApprovals;
    }

    receive() external payable {}

    /**
     * @notice Computes the unique proposal identifier from its parameters.
     * @dev Uses ABI encoding with full padding to prevent hash collisions
     *      between proposals with different parameter boundaries.
     */
    function computeProposalId(
        address recipient,
        uint256 amount,
        string memory memo,
        uint256 nonce
    ) public pure returns (bytes32) {
        return keccak256(abi.encode(recipient, amount, memo, nonce));
    }

    /**
     * @notice Creates a new withdrawal proposal.
     * @param recipient The address to receive funds
     * @param amount The amount of ETH to send
     * @param memo A human-readable description of the proposal
     */
    function createProposal(
        address recipient,
        uint256 amount,
        string memory memo
    ) external onlySigner nonReentrant returns (bytes32) {
        require(recipient != address(0), "Invalid recipient");
        require(amount > 0, "Amount must be positive");
        require(bytes(memo).length > 0 && bytes(memo).length <= 256, "Invalid memo length");

        uint256 nonce = globalNonce++;
        bytes32 proposalId = computeProposalId(recipient, amount, memo, nonce);

        Proposal storage proposal = proposals[proposalId];
        require(proposal.recipient == address(0), "Proposal already exists");

        proposal.recipient = recipient;
        proposal.amount = amount;
        proposal.memo = memo;
        proposal.nonce = nonce;
        proposal.executed = false;
        proposal.approvalCount = 0;

        emit ProposalCreated(proposalId, recipient, amount, memo);
        return proposalId;
    }

    /**
     * @notice Approves a proposal. Requires the signer to verify proposal details.
     * @dev Signer must provide the original parameters to recompute and verify the proposalId,
     *      ensuring they have reviewed the actual proposal content.
     */
    function approveProposal(
        address recipient,
        uint256 amount,
        string memory memo,
        uint256 nonce
    ) external onlySigner nonReentrant {
        bytes32 proposalId = computeProposalId(recipient, amount, memo, nonce);
        Proposal storage proposal = proposals[proposalId];

        require(proposal.recipient != address(0), "Proposal does not exist");
        require(!proposal.executed, "Already executed");
        require(!proposal.hasApproved[msg.sender], "Already approved");

        proposal.hasApproved[msg.sender] = true;
        proposal.approvalCount++;

        emit ProposalApproved(proposalId, msg.sender);
    }

    /**
     * @notice Executes a fully-approved proposal.
     * @dev Checks-effects-interactions pattern: state updated before transfer.
     */
    function executeProposal(bytes32 proposalId) external onlySigner nonReentrant {
        Proposal storage proposal = proposals[proposalId];

        require(proposal.recipient != address(0), "Proposal does not exist");
        require(!proposal.executed, "Already executed");
        require(proposal.approvalCount >= requiredApprovals, "Insufficient approvals");
        require(address(this).balance >= proposal.amount, "Insufficient balance");

        // Effects before interactions
        proposal.executed = true;

        // Interaction
        (bool success, ) = proposal.recipient.call{value: proposal.amount}("");
        require(success, "Transfer failed");

        emit ProposalExecuted(proposalId, proposal.recipient, proposal.amount);
    }

    /**
     * @notice Allows owner to add a new signer (still requires multisig for withdrawals).
     */
    function addSigner(address newSigner) external onlyOwner {
        require(newSigner != address(0), "Invalid address");
        require(!isSigner[newSigner], "Already a signer");
        require(signers.length < MAX_SIGNERS, "Max signers reached");

        isSigner[newSigner] = true;
        signers.push(newSigner);

        emit SignerAdded(newSigner);
    }

    /**
     * @notice Allows owner to remove a signer.
     */
    function removeSigner(address signer) external onlyOwner {
        require(isSigner[signer], "Not a signer");
        require(signers.length > requiredApprovals, "Would break threshold");

        isSigner[signer] = false;

        for (uint256 i = 0; i < signers.length; i++) {
            if (signers[i] == signer) {
                signers[i] = signers[signers.length - 1];
                signers.pop();
                break;
            }
        }

        emit SignerRemoved(signer);
    }

    /**
     * @notice Updates the required approval threshold.
     */
    function setRequiredApprovals(uint256 newThreshold) external onlyOwner {
        require(newThreshold > 0, "Need at least 1");
        require(newThreshold <= signers.length, "Threshold exceeds signers");
        requiredApprovals = newThreshold;
    }

    function getSigners() external view returns (address[] memory) {
        return signers;
    }

    function getProposalApprovalStatus(bytes32 proposalId, address signer) external view returns (bool) {
        return proposals[proposalId].hasApproved[signer];
    }
}
